SELECT a.task_id, a.conf_id, a.cnof_name as task_name, a.grid_id, cc.grid_name, a.keeper_name, a.start_time, a.end_time, a.inspection_time, a.create_time, a.task_status, a.conf_desc as task_desc, a.retroaction, DATE_FORMAT(a.create_time,'%Y-%m-%d') create_date, a.inspection_start_time, a.inspection_end_time, CONCAT(a.inspection_start_time,'至',a.inspection_end_time) AS inspection_period, a.feedback_keeper_id, a.feedback_end, b.keeper_name feedbackKeeperName FROM bm_inspection_task a left join bm_gridkeeper b on a.feedback_keeper_id = b.keeper_id LEFT JOIN bm_grid cc ON a.grid_id = cc.grid_id WHERE a.send_flag = 1
AND ((a.task_status = '1' and a.feedback_keeper_id = #{feedbackKeeperId,jdbcType=VARCHAR}) or a.task_status = '2')
AND a.task_status = #{taskStatus,jdbcType=VARCHAR}
AND a.feedback_keeper_id = #{feedbackKeeperId,jdbcType=VARCHAR}
${dataScope}
AND a.delete_flag = #{deleteFlag}
and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') >= #{startDate}
and DATE_FORMAT(a.inspection_time,'%Y-%m-%d') <= #{endDate}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{createStartTime}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{createEndTime}
AND a.grid_id LIKE concat('%',#{gridId},'%')
AND a.cnof_name LIKE concat('%',#{taskName},'%')
AND FIND_IN_SET(#{keeperId,jdbcType=VARCHAR},a.keeper_id)
AND a.conf_id = #{confId,jdbcType=VARCHAR}
AND a.keeper_name LIKE concat('%',#{keeperName},'%')
AND a.feedback_end = #{feedbackEnd,jdbcType=VARCHAR}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{taskDistributionStartTime}
and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{taskDistributionEndTime}
AND b.keeper_name LIKE concat('%',#{feedbackKeeperName},'%')
order by DATE_FORMAT(a.create_time,'%Y-%m-%d')
desc
asc
order by a.inspection_start_time
desc
asc
,a.inspection_end_time
desc
asc
order by a.create_time
desc
asc
order by a.inspection_time
desc
asc
ORDER BY create_date DESC,a.inspection_start_time DESC,a.inspection_end_time DESC,DATE_FORMAT(a.create_time,'%H:%i:%s') DESC

SELECT a.conf_id, a.cnof_name, a.grid_id, b.grid_name, a.keeper_name, a.creator, a.create_time, a.modifier,
    a.update_time, a.creator, a.delete_flag, a.conf_status, a.data_time, a.is_assign
FROM bm_inspection_conf a LEFT JOIN bm_grid b ON a.grid_id = b.grid_id
WHERE a.delete_flag = 0

    ${dataScope}


    AND a.grid_id = #{gridId,jdbcType=VARCHAR}


    AND a.cnof_name LIKE CONCAT('%', #{cnofName}, '%')


    AND a.keeper_name LIKE CONCAT('%', #{keeperName}, '%')


    AND a.conf_status = #{confStatus}


    AND a.creator LIKE CONCAT('%', #{creator}, '%')


    AND a.modifier LIKE CONCAT('%', #{modifier}, '%')


    and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= #{createStartDate}


    and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= #{createEndDate}


    and DATE_FORMAT(a.update_time,'%Y-%m-%d') >= #{modifyStartDate}


    and DATE_FORMAT(a.update_time,'%Y-%m-%d') <= #{modifyEndDate}


    order by a.create_time DESC


    order by a.update_time DESC


    order by a.create_time ASC


    order by a.update_time ASC
